import{z as s,x as A,o as r,c as d,q as B,j as t,D as e,d as E,s as i,S as l,b as n}from"./chunks/framework.C8m1ZpeB.js";const b=JSON.parse('{"title":"国际银行与跨境中介","description":"","frontmatter":{"title":"国际银行与跨境中介","date":"2026-09-18T00:00:00.000Z","section":"econ"},"headers":[],"relativePath":"econ/bm-international-banking.md","filePath":"econ/bm-international-banking.md","lastUpdated":1791413859000}'),p={name:"econ/bm-international-banking.md"};function D(c,a,h,C,m,f){const o=A("Mermaid");return r(),d("div",null,[a[2]||(a[2]=B('<h1 id="国际银行与跨境中介" tabindex="-1">国际银行与跨境中介 <a class="header-anchor" href="#国际银行与跨境中介" aria-label="Permalink to &quot;国际银行与跨境中介&quot;">​</a></h1><div class="epigraph"><p>银行早在国家之前就把资产负债表铺到了国境之外，最后贷款人却住在国境之内——这个错位是国际银行一切问题的母题。</p><footer>—— 据 McGuire–von Peter 2012、Cetorelli–Goldberg 2012 整理</footer></div><p><a href="/econ/bm-lender-of-last-resort">上一课</a>把最后贷款人写成协调装置，并给出一条规则：弹性沿可跑负债的分布走。但负债的分布不分国界：非美银行持有天量美元资产、靠短美元批发滚动，而本国央行印不出美元。主干课的 <a href="/econ/dollar-swap-lines">互换线</a>钉过互换线的机制与资格政治；本课补结构：全球银行怎么配置资产负债表、冲击怎么沿银行内部的资金线出口、监管与处置的管辖权错位在哪里，以及上一课的规则在跨境条件下断在哪一步。后课默认已经读完本课。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>2008 年的挤兑不只发生在美国机构：欧洲银行靠外汇互换与短期批发滚动美元账本，市场关闭后它们是同一场协调博弈的玩家，却在美联储的贴现窗口之外。为什么跨境中介放大而非分散了系统性：期限错配叠上<strong>币种错配</strong>，且后者的弹性工具天然缺位——没有一个世界央行发行美元版的 outside money（<a href="/econ/dollar-dominance">美元主导</a>钉过计价、中介与官方地板的捆绑；本课只管银行表内，不重写货币体系）。</p><p><span class="marginnote">术语翻译：「币种错配」是资产与负债的计价货币对不上——资产端持美元抵押债、负债端靠短期美元滚动；一旦美元融资停滚，本国央行帮不上忙，因为它只印本币。</span></p><h3 id="两个解剖" tabindex="-1">两个解剖 <a class="header-anchor" href="#两个解剖" aria-label="Permalink to &quot;两个解剖&quot;">​</a></h3><p><strong>结构解剖</strong>：全球银行以内部资本市场运转——Cetorelli–Goldberg 2012：母行向海外分支配置资金，危机时收紧回收；单国冲击于是沿银行内部的资金线出口到东道国，货币政策的国际传导写成资产负债表操作，而不是汇率。<strong>杠杆解剖</strong>：Adrian–Shin 的杠杆顺周期——资产涨、杠杆目标推动再加杠杆；Shin 2012 的「银行过剩」：核心欧洲银行借短美元、投美国证券化——跨境信贷的量由杠杆目标而非储蓄缺口决定。这与 <a href="/econ/global-financial-cycle">全球金融周期</a>相接而层次不同：Rey 的口径是总量与价格的共动，这里是银行表内的微结构。</p><p><span class="marginnote">美联储互换线存量 2008 年 12 月峰值约 5830 亿美元；2020 年重启后对五大央行常设、其余应急——跨境弹性从应急件变成常设件。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>把跨境问题的坐标写成三行。<strong>谁持有</strong>：集团的资本与流动性放在哪个格子里——放在总部，东道国看到的是「壳」；放在分支，母国失去对风险的控制点。<strong>押什么</strong>：美元缺口用什么滚——外汇互换市场有期限上限，长缺口只能靠不断短滚，可跑性按第一课的定义成立。<strong>谁接住</strong>：home 与 host 的监管分工、处置没有国际法院——三难（金融稳定、银行一体化、国家自主）是定性框架，三者取二。读任何一家国际银行，先找这三行各自的落点，再谈系统性。</p><p><span class="marginnote">数字实例：一家欧洲银行持 1000 亿美元资产、只有 600 亿稳定负债，缺口 400 亿只能滚动；外汇互换市场期限通常不过 3 个月，等于每年要把这 400 亿续 4 次以上——每一次续不上，都是一场小型挤兑。</span></p>',12)),(r(),t(l,null,{default:e(()=>[i(o,{id:"mermaid-34",class:"mermaid",graph:"flowchart%20TD%0A%20%20EU%5B%22%E9%9D%9E%E7%BE%8E%E9%93%B6%E8%A1%8C%EF%BC%9A%E7%BE%8E%E5%85%83%E8%B5%84%E4%BA%A7%22%5D%20--%3E%20FUND%5B%22%E7%9F%AD%E7%BE%8E%E5%85%83%E6%89%B9%E5%8F%91%E4%B8%8E%E5%A4%96%E6%B1%87%E4%BA%92%E6%8D%A2%22%5D%0A%20%20FUND%20--%3E%7C%222008%20%E5%81%9C%E6%BB%9A%22%7C%20GAP%5B%22%E5%BC%B9%E6%80%A7%E7%BC%BA%E4%BD%8D%EF%BC%9A%E6%9C%AC%E5%9B%BD%E5%A4%AE%E8%A1%8C%E5%8D%B0%E4%B8%8D%E5%87%BA%E7%BE%8E%E5%85%83%22%5D%0A%20%20GAP%20--%3E%20SWAP%5B%22%E4%BA%92%E6%8D%A2%E7%BA%BF%EF%BC%9A%E5%9B%BD%E9%99%85%E6%9C%80%E5%90%8E%E8%B4%B7%E6%AC%BE%E4%BA%BA%22%5D%0A%20%20SWAP%20--%3E%20LEND%5B%22%E5%90%8C%E8%A1%8C%E5%A4%AE%E8%A1%8C%E4%BB%A5%E6%9C%AC%E5%B8%81%E6%8A%B5%E6%8A%BC%E8%BD%AC%E8%B4%B7%22%5D%20--%3E%20BACK%5B%22%E9%93%BE%E4%B8%8A%E5%8D%8F%E8%B0%83%E6%81%A2%E5%A4%8D%22%5D%0A%20%20GAP%20--%3E%20SELF%5B%22%E6%97%A0%E7%BA%BF%E8%B5%84%E6%A0%BC%EF%BC%9A%E5%82%A8%E5%A4%87%E8%87%AA%E6%88%91%E4%BF%9D%E9%99%A9%22%5D%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[E(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=n("h2",{id:"机制",tabindex:"-1"},[E("机制 "),n("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=n("p",null,[E("互换线是上一课 LOLR 的跨境移植：美联储对合格同行央行承诺大额美元互换，同行以本币抵押转贷本国银行——协调装置的形状不变（移动阈值、删坏均衡），只是 outside money 的发行被外包给双边协议。资格不均意味着有些链上的协调问题无解：拿不到互换线的银行只能自我保险，靠积累储备度日，而储备积累本身有全球失衡的代价——"),n("a",{href:"/econ/original-sin"},"原罪"),E("的家族问题在银行层重现：本币借不到外币长债，缺口只能靠短期外币滚动。常设化是本轮的净变化：从应急件到常设件，正是「装置跟着负债搬家」这条单线在国境上的最后一格；缺口没有消失，只是被制度覆盖的部分变大了。")],-1)),(r(),t(l,null,{default:e(()=>[i(o,{id:"mermaid-41",class:"mermaid",graph:"flowchart%20TD%0A%20%20HOS%5B%22%E4%B8%9C%E9%81%93%E5%9B%BD%E5%8F%91%E7%94%9F%E5%8D%95%E5%9B%BD%E5%86%B2%E5%87%BB%22%5D%20--%3E%20SUB%5B%22%E5%BD%93%E5%9C%B0%E5%88%86%E6%94%AF%E5%8F%97%E6%8D%9F%E3%80%81%E4%BA%8F%E6%8D%9F%E4%B8%8A%E4%BC%A0%22%5D%0A%20%20SUB%20--%3E%20HO%5B%22%E6%AF%8D%E8%A1%8C%E6%94%B6%E7%B4%A7%E5%86%85%E9%83%A8%E8%B5%84%E9%87%91%E9%85%8D%E7%BD%AE%22%5D%0A%20%20HO%20--%3E%20CUT%5B%22%E5%AF%B9%E7%AC%AC%E4%B8%89%E5%9B%BD%E5%88%86%E6%94%AF%E5%90%8C%E6%A0%B7%E5%89%8A%E5%87%8F%E6%94%BE%E8%B4%B7%22%5D%0A%20%20CUT%20--%3E%20OUT%5B%22%E5%86%B2%E5%87%BB%E5%87%BA%E5%8F%A3%E5%88%B0%E6%97%A0%E5%85%B3%E7%9A%84%E4%B8%9C%E9%81%93%E5%9B%BD%22%5D%0A%20%20HO%20--%3E%20HOME%5B%22%E6%AF%8D%E5%9B%BD%E4%BF%A1%E8%B4%B7%E5%90%8C%E6%AD%A5%E6%94%B6%E7%B4%A7%22%5D%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[E(" Loading... ",-1)])]),_:1})),a[5]||(a[5]=B('<h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>不重讲互换线的账务与资格细节（主干已钉）；主权财政面不展开——<a href="/econ/eurozone-debt-crisis">欧洲主权债务危机</a>与<a href="/econ/east-asian-crisis">东亚危机</a>已钉银行—主权孪生回路，本课在银行侧；<a href="/econ/capital-controls">资本管制</a>的楔子打在边界上，对集团内部套利只是部分闸，不重复。度量有一个坑：跨境债权的 BIS 数据有国籍与驻地两种口径，混用会放大或缩小敞口——用数字前先对口径。处置与恢复计划只点名：它属于处置制度的工程，不属于本课的理论。</p><p><span class="marginnote">直觉类比：金融稳定、银行一体化、国家自主像三条凳子腿只够坐两个人——危机时东道国想先保本地储户（国家自主），母国想先保集团（一体化），系统性稳定反而没有谁独占负责。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>国际银行的母题：表在多国、LOLR 在一国；币种错配叠期限错配。</li><li>全球银行用内部资本市场搬运流动性，冲击沿资金线出口（Cetorelli–Goldberg 2012）。</li><li>跨境信贷的量由杠杆目标驱动，不是储蓄缺口（Adrian–Shin；Shin 2012）。</li><li>互换线把协调装置外包给双边协议；资格不均是常态而非例外。</li><li>监管与处置的管辖权错位是三难：稳定、一体化、国家自主取二。</li><li>出处：McGuire–von Peter 2012；Cetorelli–Goldberg 2012；Shin 2012；Rey 2013。</li></ul>',5))])}const u=s(p,[["render",D]]);export{b as __pageData,u as default};
